type Server struct {
	mu       sync.Mutex
	clients  map[string]*Client
	channels map[string]*channel
}

type channel struct {
	name    string
	members map[string]*Client
}

type Message struct {
	Command string
	Params  []string
}

func main() {
	addr := flag.String("addr", ":6667", "listen address")
	flag.Parse()
	s := &Server{clients: map[string]*Client{}, channels: map[string]*channel{}}
	ln, err := net.Listen("tcp", *addr)
	if err != nil {
		log.Fatal(err)
	}
	for {
		conn, err := ln.Accept()
		if err != nil {
			log.Fatal(err)
		}
		go s.serve(conn)
	}
}
